describe( 'ObjectLoader.parseObject() - hierarchies, animations and LOD', () => {

	it( 'parses children recursively and passes the resource libraries down', () => {

		const geometry = new BufferGeometry();
		const material = new MeshBasicMaterial();

		const group = parse(
			{
				type: 'Group',
				uuid: 'root',
				children: [
					{ type: 'Mesh', uuid: 'child-1', geometry: 'geo', material: 'mat' },
					{
						type: 'Group',
						uuid: 'child-2',
						children: [ { type: 'Mesh', uuid: 'grand-child', geometry: 'geo', material: 'mat' } ]
					}
				]
			},
			{ geometries: { geo: geometry }, materials: { mat: material } }
		);

		expect( group.children ).toHaveLength( 2 );
		expect( group.children[ 0 ].uuid ).toBe( 'child-1' );
		expect( group.children[ 0 ].parent ).toBe( group );
		expect( group.children[ 0 ].geometry ).toBe( geometry );
		expect( group.children[ 0 ].material ).toBe( material );

		const grandChild = group.children[ 1 ].children[ 0 ];
		expect( grandChild.uuid ).toBe( 'grand-child' );
		expect( grandChild.parent ).toBe( group.children[ 1 ] );
		expect( grandChild.material ).toBe( material );

	} );

	it( 'creates an empty children array when no children are serialized', () => {

		expect( parse( { type: 'Group', uuid: 'g' } ).children ).toHaveLength( 0 );

	} );

	it( 'resolves animations from the animation library', () => {

		const clipA = new AnimationClip( 'clip-a', 1, [] );
		const clipB = new AnimationClip( 'clip-b', 2, [] );

		const object = parse(
			{ type: 'Group', uuid: 'g', animations: [ 'a', 'b' ] },
			{ animations: { a: clipA, b: clipB } }
		);

		expect( object.animations ).toEqual( [ clipA, clipB ] );

	} );

	it( 'restores LOD levels from existing children', () => {

		const lod = parse( {
			type: 'LOD',
			uuid: 'lod',
			autoUpdate: false,
			children: [ { type: 'Object3D', uuid: 'level-far' }, { type: 'Object3D', uuid: 'level-near' } ],
			levels: [
				{ object: 'level-far', distance: 50 },
				{ object: 'level-near', distance: 10, hysteresis: 0.25 }
			]
		} );

		expect( lod ).toBeInstanceOf( LOD );
		expect( lod.autoUpdate ).toBe( false );
		expect( lod.levels ).toHaveLength( 2 );
		expect( lod.levels[ 0 ].object.uuid ).toBe( 'level-near' );
		expect( lod.levels[ 0 ].distance ).toBe( 10 );
		expect( lod.levels[ 0 ].hysteresis ).toBe( 0.25 );
		expect( lod.levels[ 1 ].object.uuid ).toBe( 'level-far' );
		expect( lod.levels[ 1 ].distance ).toBe( 50 );
		expect( lod.levels[ 1 ].hysteresis ).toBe( 0 );

	} );

	it( 'ignores LOD levels that reference unknown objects', () => {

		const lod = parse( {
			type: 'LOD',
			uuid: 'lod',
			children: [ { type: 'Object3D', uuid: 'known' } ],
			levels: [ { object: 'unknown', distance: 10 } ]
		} );

		expect( lod.levels ).toHaveLength( 0 );
		expect( lod.children ).toHaveLength( 1 );

	} );

	it( 'throws when a LOD is restored without serialized levels', () => {

		expect( () => parse( { type: 'LOD', uuid: 'lod' } ) ).toThrow( TypeError );

	} );

} );

