			expect( json ).not.toHaveProperty( 'emissive' );
			expect( json ).not.toHaveProperty( 'specular' );
			expect( json ).not.toHaveProperty( 'specularColor' );
			expect( json ).not.toHaveProperty( 'attenuationColor' );
			expect( material.color.getHex ).not.toHaveBeenCalled();
			expect( material.sheenColor.getHex ).not.toHaveBeenCalled();
			expect( material.emissive.getHex ).not.toHaveBeenCalled();
			expect( material.specular.getHex ).not.toHaveBeenCalled();
			expect( material.specularColor.getHex ).not.toHaveBeenCalled();
			expect( material.attenuationColor.getHex ).not.toHaveBeenCalled();

		} );

	} );

	describe( 'environment map options', () => {

		test( 'serializes envMapRotation, envMapIntensity, reflectivity and refractionRatio without an envMap', () => {

			const material = new Material();
			material.envMapRotation = new Euler( 0.1, 0.2, 0.3 );
			material.envMapIntensity = 0.5;
			material.reflectivity = 0.6;
			material.refractionRatio = 0.7;

			const json = material.toJSON();

			expect( json.envMapRotation ).toEqual( [ 0.1, 0.2, 0.3, 'XYZ' ] );
			expect( json.envMapIntensity ).toBe( 0.5 );
			expect( json.reflectivity ).toBe( 0.6 );
			expect( json.refractionRatio ).toBe( 0.7 );
			expect( json ).not.toHaveProperty( 'envMap' );
			expect( json ).not.toHaveProperty( 'combine' );

		} );

	} );

	describe( 'texture serialization', () => {

		test( 'serializes every supported texture slot by uuid along with its auxiliary settings', () => {

			const material = new Material();
			const meta = { textures: {}, images: {} };

			const textures = {
				diffuseRoughnessMap: createTexture( 'diffuse-roughness' ),
				clearcoatMap: createTexture( 'clearcoat' ),
				clearcoatRoughnessMap: createTexture( 'clearcoat-roughness' ),
				clearcoatNormalMap: createTexture( 'clearcoat-normal' ),
				sheenColorMap: createTexture( 'sheen-color' ),
				sheenRoughnessMap: createTexture( 'sheen-roughness' ),
				iridescenceMap: createTexture( 'iridescence' ),
				iridescenceThicknessMap: createTexture( 'iridescence-thickness' ),
				anisotropyMap: createTexture( 'anisotropy' ),
				map: createTexture( 'map' ),
				matcap: createTexture( 'matcap' ),
				alphaMap: createTexture( 'alpha' ),
				lightMap: createTexture( 'light' ),
				aoMap: createTexture( 'ao' ),
				bumpMap: createTexture( 'bump' ),
				normalMap: createTexture( 'normal' ),
				displacementMap: createTexture( 'displacement' ),
				roughnessMap: createTexture( 'roughness' ),
				metalnessMap: createTexture( 'metalness' ),
				emissiveMap: createTexture( 'emissive' ),
				specularMap: createTexture( 'specular' ),
				specularIntensityMap: createTexture( 'specular-intensity' ),
				specularColorMap: createTexture( 'specular-color' ),
				envMap: createTexture( 'env' ),
				gradientMap: createTexture( 'gradient' ),
				transmissionMap: createTexture( 'transmission' ),
				thicknessMap: createTexture( 'thickness' )
			};

			for ( const [ key, texture ] of Object.entries( textures ) ) {

				material[ key ] = texture;

			}

			material.clearcoatNormalScale = new Vector2( 0.25, 0.75 );
			material.lightMapIntensity = 1.5;
			material.aoMapIntensity = 0.75;
			material.bumpScale = 0.3;
			material.normalMapType = 1;
			material.normalScale = new Vector2( 0.4, 0.6 );
			material.displacementScale = 2.5;
			material.displacementBias = - 0.25;
			material.combine = 2;

			const json = material.toJSON( meta );

			for ( const [ key, texture ] of Object.entries( textures ) ) {

				expect( json[ key ] ).toBe( texture.uuid );
				expect( texture.toJSON ).toHaveBeenCalledTimes( 1 );
				expect( texture.toJSON ).toHaveBeenCalledWith( meta );

			}

			expect( json.clearcoatNormalScale ).toEqual( [ 0.25, 0.75 ] );
			expect( json.lightMapIntensity ).toBe( 1.5 );
			expect( json.aoMapIntensity ).toBe( 0.75 );
			expect( json.bumpScale ).toBe( 0.3 );
			expect( json.normalMapType ).toBe( 1 );
			expect( json.normalScale ).toEqual( [ 0.4, 0.6 ] );
			expect( json.displacementScale ).toBe( 2.5 );
			expect( json.displacementBias ).toBe( - 0.25 );
			expect( json.combine ).toBe( 2 );

		} );

		test( 'omits texture entries whose values are not textures', () => {

			const material = new Material();
			material.map = { isTexture: false, uuid: 'not-a-texture' };
			material.alphaMap = null;
			material.clearcoatNormalMap = { isTexture: false };
			material.clearcoatNormalScale = new Vector2( 1, 1 );

			const json = material.toJSON( { textures: {}, images: {} } );

			expect( json ).not.toHaveProperty( 'map' );
			expect( json ).not.toHaveProperty( 'alphaMap' );
			expect( json ).not.toHaveProperty( 'clearcoatNormalMap' );
			expect( json ).not.toHaveProperty( 'clearcoatNormalScale' );

		} );

		test( 'does not serialize combine for a non-texture envMap', () => {

			const material = new Material();
			material.envMap = { isTexture: false };
			material.combine = 2;

			const json = material.toJSON( { textures: {}, images: {} } );

			expect( json ).not.toHaveProperty( 'envMap' );
			expect( json ).not.toHaveProperty( 'combine' );

		} );

	} );

	describe( 'clipping planes', () => {

		test( 'omits clippingPlanes when unset or empty', () => {

			const material = new Material();

			expect( material.toJSON() ).not.toHaveProperty( 'clippingPlanes' );

			material.clippingPlanes = [];
			expect( material.toJSON() ).not.toHaveProperty( 'clippingPlanes' );

			material.clippingPlanes = null;
			expect( material.toJSON() ).not.toHaveProperty( 'clippingPlanes' );

		} );

		test( 'serializes non-empty clipping plane arrays through Plane.toJSON()', () => {

			const material = new Material();
			const planeA = new Plane( new Vector3( 0, 1, 0 ), - 2 );
			const planeB = new Plane( new Vector3( 1, 0, 0 ), 0.5 );
			material.clippingPlanes = [ planeA, planeB ];

			const json = material.toJSON();

			expect( json.clippingPlanes ).toEqual( [
				{ normal: [ 0, 1, 0 ], constant: - 2 },
				{ normal: [ 1, 0, 0 ], constant: 0.5 }
			] );

		} );

	} );

	describe( 'root object handling and texture/image caches', () => {

		test( 'root call omits textures and images when no textures were serialized', () => {

			const json = new Material().toJSON();

			expect( json ).not.toHaveProperty( 'textures' );
			expect( json ).not.toHaveProperty( 'images' );

		} );

		test( 'root call extracts cached textures and images and strips their metadata', () => {

			const material = new Material();
			const texture = createCachingTexture( 'texture-uuid', 'image-uuid' );
			material.map = texture;

			const json = material.toJSON();

			expect( texture.toJSON ).toHaveBeenCalledTimes( 1 );
			expect( typeof texture.toJSON.mock.calls[ 0 ][ 0 ] ).toBe( 'object' );
			expect( texture.toJSON.mock.calls[ 0 ][ 0 ] ).not.toBeNull();

			expect( json.map ).toBe( 'texture-uuid' );
			expect( json.textures ).toEqual( [ { uuid: 'texture-uuid', name: 'cached texture' } ] );
			expect( json.images ).toEqual( [ { uuid: 'image-uuid' } ] );
			expect( json.textures[ 0 ] ).not.toHaveProperty( 'metadata' );
			expect( json.images[ 0 ] ).not.toHaveProperty( 'metadata' );

		} );

		test( 'a string meta argument is treated as a root object and a fresh cache is created', () => {

			const material = new Material();
			const texture = createCachingTexture( 'string-texture', 'string-image' );
			material.map = texture;

			const json = material.toJSON( 'https://example.com/materials/1' );

			const passedMeta = texture.toJSON.mock.calls[ 0 ][ 0 ];
			expect( typeof passedMeta ).toBe( 'object' );
			expect( passedMeta ).not.toBe( 'https://example.com/materials/1' );
			expect( passedMeta ).toHaveProperty( 'textures' );
			expect( passedMeta ).toHaveProperty( 'images' );

			expect( json.map ).toBe( 'string-texture' );
			expect( json.textures ).toEqual( [ { uuid: 'string-texture', name: 'cached texture' } ] );
			expect( json.images ).toEqual( [ { uuid: 'string-image' } ] );

		} );

		test( 'a provided meta object is treated as non-root: no texture or image extraction occurs', () => {

			const material = new Material();
			const texture = createCachingTexture( 'shared-texture', 'shared-image' );
			material.map = texture;

			const meta = { textures: {}, images: {} };
			const json = material.toJSON( meta );

			expect( texture.toJSON ).toHaveBeenCalledWith( meta );
			expect( json.map ).toBe( 'shared-texture' );
			expect( json ).not.toHaveProperty( 'textures' );
			expect( json ).not.toHaveProperty( 'images' );

			expect( meta.textures[ 'shared-texture' ] ).toEqual( {
				metadata: { version: 4.7, type: 'Texture', generator: 'Texture.toJSON' },
				uuid: 'shared-texture',
				name: 'cached texture'
			} );
			expect( meta.images[ 'shared-image' ] ).toEqual( {
				metadata: { version: 4.7, type: 'Image', generator: 'Texture.toJSON' },
				uuid: 'shared-image'
			} );

		} );

		test( 'a provided meta object with pre-existing entries is not reduced into data.textures', () => {

			const meta = {
				textures: { existing: { metadata: { version: 4.7 }, uuid: 'existing' } },
				images: { existing: { metadata: { version: 4.7 }, uuid: 'existing' } }
			};

			const json = new Material().toJSON( meta );

			expect( json ).not.toHaveProperty( 'textures' );
			expect( json ).not.toHaveProperty( 'images' );
			expect( meta.textures.existing ).toHaveProperty( 'metadata' );
			expect( meta.images.existing ).toHaveProperty( 'metadata' );

		} );

	} );

} );
