		toJSON: jest.fn( () => ( { uuid } ) )
	};

}

function createCachingTexture( uuid, imageUuid ) {

	const texture = {
		isTexture: true,
		uuid
	};

		test( 'a provided meta object with pre-existing entries is not reduced into data.textures', () => {

