import { MeshStandardMaterial } from '/testbed/src/materials/MeshStandardMaterial.js';
import { BufferGeometry } from '/testbed/src/core/BufferGeometry.js';
import { Float32BufferAttribute } from '/testbed/src/core/BufferAttribute.js';
import { Matrix4 } from '/testbed/src/math/Matrix4.js';
import { Vector3 } from '/testbed/src/math/Vector3.js';
import { Texture } from '/testbed/src/textures/Texture.js';

const canvasTarget = { id: 'canvas' };
function makeRO(over = {}) {
  const scene = { environment: null, environmentIntensity: 1, environmentRotation: new Vector3(), fogNode: null, environmentNode: null };
  const material = new MeshStandardMaterial();
  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new Float32BufferAttribute([0,0,0,1,1,1], 3));
  const object = { matrixWorld: new Matrix4() };
  const ro = { object, material, geometry,
    context: { width: 100, height: 100 },
    renderer: { getRenderTarget: () => null, getOutputRenderTarget: () => null, getCanvasTarget: () => canvasTarget },
    scene, lightsNode: { getBuiltinLights: () => [] }, bundle: null, ...over };
  return ro;
}
const obs = (ro) => new NMO({ material: ro.material, context: {}, scene: ro.scene, object: { isSkinnedMesh: false } });

// instancing
{
  const ro = makeRO(); const o = obs(ro);
  ro.object.isInstancedMesh = true;
  ro.object.instanceMatrix = { version: 0 };
  ro.object.instanceColor = null;
  ro.object.morphTexture = null;
  console.log('inst base', o.equals(ro, [], 1));
  ro.object.instanceMatrix.version = 3;
  console.log('inst matrix', o.equals(ro, [], 2));
  console.log('inst after', o.equals(ro, [], 3));
  ro.object.instanceColor = { version: 1 };
  console.log('inst color', o.equals(ro, [], 4));
  ro.object.morphTexture = { version: 1 };
  console.log('inst morphTex', o.equals(ro, [], 5));
  console.log('inst morphTex after', o.equals(ro, [], 6));
}
// batching
{
  const ro = makeRO(); const o = obs(ro);
  ro.object.isBatchedMesh = true;
  ro.object._matricesTexture = { version: 0 };
  ro.object._colorsTexture = null;
  ro.object._indirectTexture = { version: 0 };
  console.log('batch base', o.equals(ro, [], 1));
  ro.object._indirectTexture.version = 2;
  console.log('batch indirect', o.equals(ro, [], 2));
  ro.object._colorsTexture = { version: 1 };
  console.log('batch colors', o.equals(ro, [], 3));
  console.log('batch after', o.equals(ro, [], 4));
  ro.object._matricesTexture.version = 7;
  console.log('batch matrices', o.equals(ro, [], 5));
  console.log('batch final', o.equals(ro, [], 6));
}
// lights
{
  const tex = new Texture();
  const lights = [{ isSpotLight: true, map: tex }, { castShadow: true, shadow: { mapSize: { width: 512, height: 512 } } }];
  const ro = makeRO({ lightsNode: { getBuiltinLights: () => lights } });
  const o = obs(ro);
  let ld = o.getLightsData(lights, []);
  console.log('lights ld', ld, 'base', o.equals(ro, ld, 1));
  tex.version = 1;
  ld = o.getLightsData(lights, []);
  console.log('light map ver', o.equals(ro, ld, 2));
  console.log('light map after', o.equals(ro, ld, 3));
  lights[1].shadow.mapSize.width = 1024;
  ld = o.getLightsData(lights, []);
  console.log('light shadow', o.equals(ro, ld, 4));
  console.log('light shadow after', o.equals(ro, ld, 5));
  console.log('stored', o.getRenderObjectData(ro).lights);
}
// environment
{
  const ro = makeRO();
  ro.scene.environment = new Texture();
  const o = obs(ro);
  console.log('env base', o.equals(ro, [], 1));
  ro.scene.environmentIntensity = 2;
  console.log('env intensity', o.equals(ro, [], 2));
  ro.scene.environmentRotation.set(0.1, 0.2, 0.3);
  console.log('env rotation', o.equals(ro, [], 3));
  console.log('env after', o.equals(ro, [], 4), o.getRenderObjectData(ro).environmentIntensity);
}
// center
{
  const ro = makeRO();
  ro.object.center = new Vector3();
  const o = obs(ro);
  console.log('center base', o.equals(ro, [], 1));
  ro.object.center.set(1, 2, 3);
  console.log('center changed', o.equals(ro, [], 2));
  console.log('center after', o.equals(ro, [], 3), o.getRenderObjectData(ro).center);
}
// morph
{
  const ro = makeRO();
  ro.object.morphTargetInfluences = [0, 0];
  const o = obs(ro);
  console.log('morph base', o.equals(ro, [], 1));
  ro.object.morphTargetInfluences[1] = 0.7;
  console.log('morph changed', o.equals(ro, [], 2));
  console.log('morph after', o.equals(ro, [], 3));
}
// bundle
{
  const ro = makeRO({ bundle: { version: 0 } });
  const o = obs(ro);
  console.log('bundle base', o.equals(ro, [], 1), o.getRenderObjectData(ro).version);
  ro.bundle.version = 5;
  console.log('bundle changed', o.equals(ro, [], 2), o.getRenderObjectData(ro).version);
}
EOF
