{"command": "cd /testbed && cat > test/materials/nodes/manager/NodeMaterialObserver/equals.test.js <<'EOF'
import NodeMaterialObserver from '../../../../../src/materials/nodes/manager/NodeMaterialObserver.js';
import { MeshStandardMaterial } from '../../../../../src/materials/MeshStandardMaterial.js';
import { BufferGeometry } from '../../../../../src/core/BufferGeometry.js';
import { Float32BufferAttribute } from '../../../../../src/core/BufferAttribute.js';
import { InterleavedBufferAttribute } from '../../../../../src/core/InterleavedBufferAttribute.js';
import { InstancedInterleavedBuffer } from '../../../../../src/core/InstancedInterleavedBuffer.js';
import { Matrix4 } from '../../../../../src/math/Matrix4.js';
import { Vector3 } from '../../../../../src/math/Vector3.js';
import { Texture } from '../../../../../src/textures/Texture.js';

/**
 * Creates a minimal renderer stub whose output target never changes.
 *
 * @return {Object} The renderer stub.
 */
function createRenderer() {

	const canvasTarget = { isCanvasTarget: true };

	return {
		getRenderTarget: () => null,
		getOutputRenderTarget: () => null,
		getCanvasTarget: () => canvasTarget
	};

}

/**
 * Creates a scene stub as expected by the observer.
 *
 * @param {Object} [overrides] - Values that override the defaults.
 * @return {Object} The scene stub.
 */
function createScene( overrides = {} ) {

	return {
		environment: null,
		environmentIntensity: 1,
		environmentRotation: new Vector3(),
		fogNode: null,
		environmentNode: null,
		...overrides
	};

}

/**
 * Creates a geometry with a single position attribute.
 *
 * @return {BufferGeometry} The geometry.
 */
function createGeometry() {

	const geometry = new BufferGeometry();
	geometry.setAttribute( 'position', new Float32BufferAttribute( [ 0, 0, 0, 1, 1, 1 ], 3 ) );

	return geometry;

}

/**
 * Creates a render object stub with all the properties observed by `equals()`.
 *
 * @param {Object} [overrides] - Values that override the defaults.
 * @return {Object} The render object stub.
 */
function createRenderObject( overrides = {} ) {

	return {
		object: { matrixWorld: new Matrix4() },
		material: new MeshStandardMaterial(),
		geometry: createGeometry(),
		context: { width: 100, height: 100 },
		renderer: createRenderer(),
		scene: createScene(),
		lightsNode: { getBuiltinLights: () => [] },
		bundle: null,
		...overrides
	};

}

/**
 * Creates an observer for the given render object.
 *
 * @param {Object} renderObject - The render object.
 * @return {NodeMaterialObserver} The observer.
 */
function createObserver( renderObject ) {

	return new NodeMaterialObserver( {
		material: renderObject.material,
		context: {},
		scene: renderObject.scene,
		object: { isSkinnedMesh: false }
	} );

}

describe( 'NodeMaterialObserver.equals', () => {

	describe( 'initial state', () => {

		it( 'returns true and stores the initial state on the first observation', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			const renderObjectData = observer.getRenderObjectData( renderObject );

			expect( renderObjectData.worldMatrix.equals( renderObject.object.matrixWorld ) ).toBe( true );
			expect( renderObjectData.geometryId ).toBe( renderObject.geometry.id );
			expect( renderObjectData.bufferWidth ).toBe( 100 );
			expect( renderObjectData.bufferHeight ).toBe( 100 );
			expect( renderObjectData.materialVersion ).toBe( 0 );

		} );

		it( 'returns true for as long as nothing changes', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			for ( let renderId = 1; renderId <= 5; renderId ++ ) {

				expect( observer.equals( renderObject, [], renderId ) ).toBe( true );

			}

			expect( observer.getMaterialData( renderObject.material )._version ).toBe( 0 );

		} );

	} );

	describe( 'world matrix', () => {

		it( 'returns false once when the world matrix changed and reports true afterwards', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.object.matrixWorld.makeTranslation( 1, 2, 3 );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).worldMatrix.equals( renderObject.object.matrixWorld ) ).toBe( true );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

	} );

	describe( 'material', () => {

		it( 'detects a changed scalar property and increments the material version exactly once', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.material.opacity = 0.25;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getMaterialData( renderObject.material ).opacity ).toBe( 0.25 );
			expect( observer.getMaterialData( renderObject.material )._version ).toBe( 1 );

			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );
			expect( observer.getMaterialData( renderObject.material )._version ).toBe( 1 );

		} );

		it( 'detects a changed color value and stores a copy of it', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.material.color.set( 0.5, 0.25, 0.125 );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );

			const materialData = observer.getMaterialData( renderObject.material );
			expect( materialData.color.equals( renderObject.material.color ) ).toBe( true );
			expect( materialData.color ).not.toBe( renderObject.material.color );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects a changed clonable object property', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.material.envMapRotation.set( 0.5, 0, 0 );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'ignores material properties that are not monitored', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.material.name = 'not-monitored';
			renderObject.material.visible = false;
			renderObject.material.userData.custom = 42;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( true );
			expect( observer.getMaterialData( renderObject.material )._version ).toBe( 0 );

		} );

		it( 'tracks a newly assigned texture', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			const texture = new Texture();
			renderObject.material.map = texture;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );

			const materialData = observer.getMaterialData( renderObject.material );
			expect( materialData.map ).toEqual( { id: texture.id, version: 0, cacheVersion: 0 } );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'tracks a texture version change', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			const texture = new Texture();
			renderObject.material.map = texture;

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObject, [], 2 ) ).toBe( true );

			texture.needsUpdate = true;

			expect( observer.equals( renderObject, [], 3 ) ).toBe( false );
			expect( observer.getMaterialData( renderObject.material ).map.version ).toBe( 1 );
			expect( observer.equals( renderObject, [], 4 ) ).toBe( true );

		} );

		it( 'tracks a disposed texture through the texture cache version', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			const texture = new Texture();
			renderObject.material.map = texture;

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObject, [], 2 ) ).toBe( true );

			texture.dispose();

			expect( observer.equals( renderObject, [], 3 ) ).toBe( false );
			expect( observer.getMaterialData( renderObject.material ).map.cacheVersion ).toBe( 1 );
			expect( observer.equals( renderObject, [], 4 ) ).toBe( true );

		} );

		it( 'tracks a removed texture', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			renderObject.material.map = new Texture();

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObject, [], 2 ) ).toBe( true );

			renderObject.material.map = null;

			expect( observer.equals( renderObject, [], 3 ) ).toBe( false );
			expect( observer.getMaterialData( renderObject.material ).map ).toBe( null );
			expect( observer.equals( renderObject, [], 4 ) ).toBe( true );

		} );

		it( 'checks the material properties only once per render for shared materials', () => {

			const material = new MeshStandardMaterial();
			const renderObjectA = createRenderObject( { material } );
			const renderObjectB = createRenderObject( { material } );
			const observer = createObserver( renderObjectA );

			expect( observer.equals( renderObjectA, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObjectB, [], 1 ) ).toBe( true );

			material.opacity = 0.5;

			// the first render object refreshes the snapshot, both have to be refreshed

			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( false );
			expect( observer.equals( renderObjectB, [], 2 ) ).toBe( false );
			expect( observer.getMaterialData( material )._version ).toBe( 1 );

			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( true );
			expect( observer.equals( renderObjectB, [], 2 ) ).toBe( true );

			// a second change inside the same render is not observed again

			material.opacity = 0.75;

			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( true );
			expect( observer.getMaterialData( material )._version ).toBe( 1 );

			// but it is observed in the next render

			expect( observer.equals( renderObjectA, [], 3 ) ).toBe( false );
			expect( observer.getMaterialData( material )._version ).toBe( 2 );

		} );

	} );

	describe( 'render buffer', () => {

		it( 'detects a changed render target size', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.context.width = 200;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).bufferWidth ).toBe( 200 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects a changed render target height', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.context.height = 512;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).bufferHeight ).toBe( 512 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

	} );

	describe( 'geometry', () => {

		it( 'detects a replaced geometry', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.geometry = createGeometry();

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).geometryId ).toBe( renderObject.geometry.id );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an attribute version change', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.geometry.attributes.position.version ++;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getGeometryData( renderObject.geometry )._version ).toBe( 1 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an added attribute', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.geometry.setAttribute( 'normal', new Float32BufferAttribute( [ 0, 0, 1 ], 3 ) );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( Object.keys( observer.getGeometryData( renderObject.geometry ).attributes ) ).toEqual( [ 'position', 'normal' ] );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects a removed attribute', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			delete renderObject.geometry.attributes.position;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( Object.keys( observer.getGeometryData( renderObject.geometry ).attributes ) ).toEqual( [] );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an interleaved attribute version change', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			const interleavedBuffer = new InstancedInterleavedBuffer( new Float32Array( 6 ), 3, 1 );
			renderObject.geometry.setAttribute( 'foo', new InterleavedBufferAttribute( interleavedBuffer, 3, 0 ) );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			const attributesData = observer.getGeometryData( renderObject.geometry ).attributes;
			expect( attributesData.foo.id ).toBe( interleavedBuffer.uuid );

			interleavedBuffer.version ++;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getGeometryData( renderObject.geometry ).attributes.foo.version ).toBe( 1 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an added index', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );
			expect( observer.getGeometryData( renderObject.geometry ).indexId ).toBe( null );

			renderObject.geometry.setIndex( [ 0, 1, 2 ] );

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getGeometryData( renderObject.geometry ).indexId ).toBe( renderObject.geometry.index.id );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects a changed draw range', () => {

			const renderObject = createRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.geometry.drawRange.count = 1;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getGeometryData( renderObject.geometry ).drawRange.count ).toBe( 1 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'checks the geometry properties only once per render for shared geometries', () => {

			const geometry = createGeometry();
			const renderObjectA = createRenderObject( { geometry } );
			const renderObjectB = createRenderObject( { geometry } );
			const observer = createObserver( renderObjectA );

			expect( observer.equals( renderObjectA, [], 1 ) ).toBe( true );
			expect( observer.equals( renderObjectB, [], 1 ) ).toBe( true );

			geometry.attributes.position.version ++;

			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( false );
			expect( observer.getGeometryData( geometry )._version ).toBe( 1 );
			expect( observer.equals( renderObjectB, [], 2 ) ).toBe( false );
			expect( observer.getGeometryData( geometry )._version ).toBe( 1 );

			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( true );
			expect( observer.equals( renderObjectB, [], 2 ) ).toBe( true );

			// a second change inside the same render is not observed again

			geometry.attributes.position.version ++;

			expect( observer.equals( renderObjectA, [], 2 ) ).toBe( true );
			expect( observer.getGeometryData( geometry )._version ).toBe( 1 );

		} );

	} );

	describe( 'morph targets', () => {

		it( 'detects changed morph target influences', () => {

			const renderObject = createRenderObject();
			renderObject.object.morphTargetInfluences = [ 0, 0, 0 ];
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.object.morphTargetInfluences[ 1 ] = 0.5;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).morphTargetInfluences[ 1 ] ).toBe( 0.5 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

	} );

	describe( 'instancing', () => {

		/**
		 * Creates an instanced render object.
		 *
		 * @return {Object} The render object stub.
		 */
		function createInstancedRenderObject() {

			const renderObject = createRenderObject();
			renderObject.object.isInstancedMesh = true;
			renderObject.object.instanceMatrix = { version: 0 };
			renderObject.object.instanceColor = null;
			renderObject.object.morphTexture = null;

			return renderObject;

		}

		it( 'detects a changed instance matrix version', () => {

			const renderObject = createInstancedRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.object.instanceMatrix.version = 3;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).instanceMatrixVersion ).toBe( 3 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an assigned instance color', () => {

			const renderObject = createInstancedRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.object.instanceColor = { version: 2 };

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).instanceColorVersion ).toBe( 2 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an assigned morph texture', () => {

			const renderObject = createInstancedRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.object.morphTexture = { version: 1 };

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).morphTextureVersion ).toBe( 1 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

	} );

	describe( 'batching', () => {

		/**
		 * Creates a batched render object.
		 *
		 * @return {Object} The render object stub.
		 */
		function createBatchedRenderObject() {

			const renderObject = createRenderObject();
			renderObject.object.isBatchedMesh = true;
			renderObject.object._matricesTexture = { version: 0 };
			renderObject.object._colorsTexture = null;
			renderObject.object._indirectTexture = { version: 0 };

			return renderObject;

		}

		it( 'detects a changed matrices texture version', () => {

			const renderObject = createBatchedRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

			renderObject.object._matricesTexture.version = 4;

			expect( observer.equals( renderObject, [], 2 ) ).toBe( false );
			expect( observer.getRenderObjectData( renderObject ).matricesTextureVersion ).toBe( 4 );
			expect( observer.equals( renderObject, [], 3 ) ).toBe( true );

		} );

		it( 'detects an assigned colors texture', () => {

			const renderObject = createBatchedRenderObject();
			const observer = createObserver( renderObject );

			expect( observer.equals( renderObject, [], 1 ) ).toBe( true );

