import LoopNode from '/testbed/src/nodes/utils/LoopNode.js';

function createBuilder() {
	const builder = {
		tab: '\t',
		flow: { code: '' },
		flowBlock: { id: 'root' },
		calls: [],
		updateFlowCode: '',
		addFlowCode( code ) { this.flow.code += code; return this; },
		addFlowTab() { this.tab += '\t'; return this; },
		removeFlowTab() { this.tab = this.tab.slice( 0, - 1 ); return this; },
		getVar( type, name ) { this.calls.push( [ 'getVar', type, name ] ); return `${type} ${name}`; },
		generateConst( type, value ) {
			this.calls.push( [ 'generateConst', type, value ] );
			if ( type === 'float' ) return Number.isInteger( value ) ? value.toFixed( 1 ) : String( value );
			if ( type === 'uint' ) return `${Math.trunc( value )}u`;
			return String( Math.trunc( value ) );
		},
		flowStagesNode( node, stage ) { this.calls.push( [ 'flowStagesNode', node, stage ] ); return { code: this.updateFlowCode }; }
	};
	return builder;
}

function node( value, nodeType = 'int' ) {
	return { isNode: true, getNodeType: () => nodeType, build: ( b, t ) => value };
}

function run( params, stackSnippet = 'body-code' ) {
	const loopNode = new LoopNode( params );
	const stackNode = { build: ( b, t ) => stackSnippet };
	const returnsNode = { build: () => 'returns' };
	const properties = { stackNode, returnsNode };
	loopNode.getProperties = () => properties;
	const builder = createBuilder();
	loopNode.generate( builder );
