import LoopNode, { Loop } from '../../../../src/nodes/utils/LoopNode.js';

/**
 * Creates a lightweight NodeBuilder stand-in which records the generated flow code
 * and the helper calls `LoopNode.generate()` relies on.
 *
 * @return {Object} The fake builder.
 */
function createBuilder() {

	const builder = {
		tab: '\t',
		flow: { code: '' },
		flowBlock: { id: 'root-flow-block' },
		calls: [],
		flowStagesCode: '\t\ti += 5;\n\t\tx = 1;\n',
		addFlowCode( code ) {

			this.flow.code += code;
			this.calls.push( [ 'addFlowCode', code ] );
			return this;

		},
		addFlowTab() {

			this.tab += '\t';
			return this;

		},
		removeFlowTab() {

			this.tab = this.tab.slice( 0, - 1 );
			return this;

		},
		getVar( type, name ) {

			this.calls.push( [ 'getVar', type, name ] );
			return `${ type } ${ name }`;

		},
		generateConst( type, value ) {

			this.calls.push( [ 'generateConst', type, value ] );

			if ( type === 'float' ) return Number.isInteger( value ) ? value.toFixed( 1 ) : String( value );
			if ( type === 'uint' ) return `${ Math.trunc( value ) }u`;
			if ( type === 'int' ) return `${ Math.trunc( value ) }`;

			return String( value );

		},
		flowStagesNode( node, stage ) {

			this.calls.push( [ 'flowStagesNode', node, stage ] );
			return { code: this.flowStagesCode };

		}
	};

	return builder;

}

/**
 * Creates a fake node used as a loop parameter, start/end value or update value.
 *
 * @param {string} snippet - The shader snippet returned by `build()`.
 * @param {string} [nodeType='int'] - The node type reported by `getNodeType()`.
 * @return {Object} The fake node.
 */
function createNode( snippet, nodeType = 'int' ) {

	return {
		isNode: true,
		getNodeType: jest.fn( () => nodeType ),
		build: jest.fn( () => snippet )
	};

}

/**
 * Runs `LoopNode.generate()` with stubbed node properties so only the loop
 * generation logic itself is exercised.
 *
 * @param {Array} params - The loop parameters (last entry is the body callback).
 * @param {Object} [options] - Additional options.
 * @param {string} [options.stackSnippet='body-code'] - Snippet returned by the stack node build.
 * @param {string} [options.returnsSnippet='returns-code'] - Snippet returned by the returns node build.
 * @param {Object} [options.updateNode] - Value of the `updateNode` property.
 * @return {Object} The generated result and the used stubs.
 */
function generate( params, options = {} ) {

	const { stackSnippet = 'body-code', returnsSnippet = 'returns-code', updateNode } = options;

	const loopNode = new LoopNode( params );

	const stackNode = { build: jest.fn( () => stackSnippet ) };
	const returnsNode = { build: jest.fn( () => returnsSnippet ) };
	const properties = { stackNode, returnsNode };

	if ( updateNode !== undefined ) properties.updateNode = updateNode;

	loopNode.getProperties = jest.fn( () => properties );

	const builder = createBuilder();
	const returnValue = loopNode.generate( builder );

	return { loopNode, builder, properties, stackNode, returnsNode, returnValue, code: builder.flow.code };

}

describe( 'LoopNode.generate', () => {

	describe( 'node parameters', () => {

		it( 'generates a counting for loop for an integer node parameter', () => {

			const param = createNode( '10' );
			const result = generate( [ param, () => {} ] );

			expect( result.code ).toBe( '\n\tfor ( int i = 0; i < 10; i ++ ) {\n\n\n\tbody-code}\n\n' );
			expect( result.builder.calls ).toEqual( [ [ 'getVar', 'int', 'i' ] ] );
			expect( param.build ).toHaveBeenCalledWith( result.builder, 'int' );
			expect( result.returnValue ).toBeUndefined();

		} );

		it( 'generates a while loop for a boolean node parameter', () => {

			const param = createNode( 'i < 10', 'bool' );
			const result = generate( [ param, () => {} ] );

			expect( result.code ).toBe( '\n\twhile ( i < 10 ) {\n\n\n\tbody-code}\n\n' );
			expect( param.build ).toHaveBeenCalledWith( result.builder, 'bool' );
			expect( result.builder.calls ).toEqual( [] );

		} );

		it( 'forces a non boolean node parameter to an int loop starting at 0', () => {

			const param = createNode( 'count', 'uint' );
			const result = generate( [ param, () => {} ] );

			expect( result.code ).toBe( '\n\tfor ( int i = 0; i < count; i ++ ) {\n\n\n\tbody-code}\n\n' );
			expect( param.build ).toHaveBeenCalledWith( result.builder, 'int' );

		} );

		it( 'derives the variable names from the parameter index for nested node parameters', () => {

			const first = createNode( '3' );
			const second = createNode( '2' );
			const result = generate( [ first, second, () => {} ] );

			expect( result.code ).toBe( '\n\tfor ( int i = 0; i < 3; i ++ ) {\n\n\t\tfor ( int j = 0; j < 2; j ++ ) {\n\n\n\t\tbody-code}\n\n\t}\n\n' );

		} );

	} );

