import { WebXRController } from '../../../../src/renderers/webxr/WebXRController.js';
import { Matrix4 } from '../../../../src/math/Matrix4.js';
import { Vector3 } from '../../../../src/math/Vector3.js';

const VISIBLE = 'visible';
const VISIBLE_BLURRED = 'visible-blurred';

/**
 * Creates a pose object as returned by XRFrame.getPose() / getJointPose().
 */
function createPose( { position = [ 0, 0, 0 ], rotationY = 0, radius = null, linearVelocity = null, angularVelocity = null } = {} ) {

	const matrix = new Matrix4();

	if ( rotationY !== 0 ) matrix.makeRotationY( rotationY );

	matrix.setPosition( position[ 0 ], position[ 1 ], position[ 2 ] );

	const pose = { transform: { matrix: matrix.toArray() } };

	if ( radius !== null ) pose.radius = radius;
	if ( linearVelocity !== null ) pose.linearVelocity = new Vector3( ...linearVelocity );
	if ( angularVelocity !== null ) pose.angularVelocity = new Vector3( ...angularVelocity );

	return pose;

}

/**
 * Creates a frame mock. Poses/joint poses are looked up by space/joint identity.
 */
function createFrame( { visibilityState = VISIBLE, poses = new Map(), jointPoses = new Map() } = {} ) {

	return {
		session: { visibilityState },
		getPose: jest.fn( ( space ) => poses.get( space ) ?? null ),
		getJointPose: jest.fn( ( joint ) => jointPoses.get( joint ) ?? null )
	};

}

describe( 'WebXRController.update', () => {

	const referenceSpace = { name: 'reference-space' };

	describe( 'guards and return value', () => {

		it( 'returns this even without any space or input source', () => {

			const controller = new WebXRController();
			const frame = createFrame();

			expect( controller.update( null, frame, referenceSpace ) ).toBe( controller );
			expect( frame.getPose ).not.toHaveBeenCalled();

		} );

		it( 'does not touch the frame when inputSource is falsy', () => {

			const controller = new WebXRController();
			controller.getTargetRaySpace();
			controller.getGripSpace();
			controller.getHandSpace();

			// a frame without a session would throw if it were dereferenced
			expect( controller.update( undefined, {}, referenceSpace ) ).toBe( controller );

		} );

		it( 'marks all existing spaces invisible when inputSource is null', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const grip = controller.getGripSpace();
			const hand = controller.getHandSpace();

			targetRay.visible = true;
			grip.visible = true;
			hand.visible = true;

			controller.update( null, createFrame(), referenceSpace );

			expect( targetRay.visible ).toBe( false );
			expect( grip.visible ).toBe( false );
			expect( hand.visible ).toBe( false );

		} );

		it( 'ignores everything while the session is visible-blurred', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const targetRaySpace = { name: 'target-ray-space' };

			// make the space visible first
			controller.update(
				{ handedness: 'right', targetRaySpace },
				createFrame( { poses: new Map( [ [ targetRaySpace, createPose( { position: [ 1, 1, 1 ] } ) ] ] ) } ),
				referenceSpace
			);

			expect( targetRay.visible ).toBe( true );

			const moves = [];
			targetRay.addEventListener( 'move', () => moves.push( 1 ) );

			const frame = createFrame( {
				visibilityState: VISIBLE_BLURRED,
				poses: new Map( [ [ targetRaySpace, createPose( { position: [ 5, 5, 5 ] } ) ] ] )
			} );

			controller.update( { handedness: 'right', targetRaySpace }, frame, referenceSpace );

			expect( frame.getPose ).not.toHaveBeenCalled();
			expect( targetRay.visible ).toBe( false );
			expect( targetRay.position.toArray() ).toEqual( [ 1, 1, 1 ] );
			expect( moves ).toHaveLength( 0 );

		} );

		it( 'does not throw when the controller has no spaces at all', () => {

			const controller = new WebXRController();
			const targetRaySpace = { name: 'target-ray-space' };
			const gripSpace = { name: 'grip-space' };

			const frame = createFrame( {
				poses: new Map( [
					[ targetRaySpace, createPose( { position: [ 1, 2, 3 ] } ) ],
					[ gripSpace, createPose( { position: [ 4, 5, 6 ] } ) ]
				] )
			} );

			expect( controller.update( { handedness: 'left', targetRaySpace, gripSpace }, frame, referenceSpace ) ).toBe( controller );

		} );

	} );

	describe( 'target ray space', () => {

		it( 'applies the target ray pose and dispatches a single move event', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const targetRaySpace = { name: 'target-ray-space' };

			const pose = createPose( {
				position: [ 1, 2, 3 ],
				rotationY: Math.PI / 2,
				linearVelocity: [ 0.5, 0, - 0.5 ],
				angularVelocity: [ 0, 1.5, 0 ]
			} );

			const frame = createFrame( { poses: new Map( [ [ targetRaySpace, pose ] ] ) } );
			const moves = [];
			targetRay.addEventListener( 'move', ( event ) => moves.push( event ) );

			const result = controller.update( { handedness: 'right', targetRaySpace }, frame, referenceSpace );

			expect( result ).toBe( controller );
			expect( frame.getPose ).toHaveBeenCalledTimes( 1 );
			expect( frame.getPose ).toHaveBeenCalledWith( targetRaySpace, referenceSpace );

			expect( targetRay.matrix.toArray() ).toEqual( pose.transform.matrix );
			expect( targetRay.matrixWorldNeedsUpdate ).toBe( true );
			expect( targetRay.position.toArray() ).toEqual( [ 1, 2, 3 ] );
			expect( targetRay.quaternion.y ).toBeCloseTo( Math.SQRT1_2 );
			expect( targetRay.quaternion.w ).toBeCloseTo( Math.SQRT1_2 );
			expect( targetRay.visible ).toBe( true );

			expect( targetRay.hasLinearVelocity ).toBe( true );
			expect( targetRay.linearVelocity.toArray() ).toEqual( [ 0.5, 0, - 0.5 ] );
			expect( targetRay.linearVelocity ).not.toBe( pose.linearVelocity );

			expect( targetRay.hasAngularVelocity ).toBe( true );
			expect( targetRay.angularVelocity.toArray() ).toEqual( [ 0, 1.5, 0 ] );
			expect( targetRay.angularVelocity ).not.toBe( pose.angularVelocity );

			expect( moves ).toHaveLength( 1 );
			expect( moves[ 0 ].type ).toBe( 'move' );

		} );

		it( 'hides the target ray and stays silent when the pose is missing', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const targetRaySpace = { name: 'target-ray-space' };

			const moves = [];
			targetRay.addEventListener( 'move', () => moves.push( 1 ) );
			targetRay.visible = true;

			const frame = createFrame();

			controller.update( { handedness: 'right', targetRaySpace }, frame, referenceSpace );

			expect( frame.getPose ).toHaveBeenCalledWith( targetRaySpace, referenceSpace );
			expect( targetRay.visible ).toBe( false );
			expect( targetRay.matrixWorldNeedsUpdate ).toBe( false );
			expect( targetRay.hasLinearVelocity ).toBe( false );
			expect( targetRay.hasAngularVelocity ).toBe( false );
			expect( moves ).toHaveLength( 0 );

		} );

		it( 'resets the velocity flags when the pose has no velocities', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const targetRaySpace = { name: 'target-ray-space' };

			controller.update(
				{ handedness: 'right', targetRaySpace },
				createFrame( {
					poses: new Map( [ [ targetRaySpace, createPose( {
						position: [ 2, 0, 0 ],
						linearVelocity: [ 1, 0, 0 ],
						angularVelocity: [ 0, 0, 2 ]
					} ) ] ] )
				} ),
				referenceSpace
			);

			expect( targetRay.hasLinearVelocity ).toBe( true );
			expect( targetRay.hasAngularVelocity ).toBe( true );

			controller.update(
				{ handedness: 'right', targetRaySpace },
				createFrame( { poses: new Map( [ [ targetRaySpace, createPose( { position: [ 3, 0, 0 ] } ) ] ] ) } ),
				referenceSpace
			);

			expect( targetRay.hasLinearVelocity ).toBe( false );
			expect( targetRay.hasAngularVelocity ).toBe( false );
			expect( targetRay.position.x ).toBe( 3 );
			// velocity vectors are only flagged, not zeroed out
			expect( targetRay.linearVelocity.toArray() ).toEqual( [ 1, 0, 0 ] );
			expect( targetRay.angularVelocity.toArray() ).toEqual( [ 0, 0, 2 ] );

		} );

		it( 'does not dispatch move events when the controller has no target ray space', () => {

			const controller = new WebXRController();
			const grip = controller.getGripSpace();
			const gripSpace = { name: 'grip-space' };

			const moves = [];
			grip.addEventListener( 'move', () => moves.push( 1 ) );

			const frame = createFrame( { poses: new Map( [ [ gripSpace, createPose( { position: [ 1, 0, 0 ] } ) ] ] ) } );

			controller.update( { handedness: 'right', gripSpace }, frame, referenceSpace );

			expect( moves ).toHaveLength( 0 );
			expect( grip.visible ).toBe( true );

		} );

	} );

	describe( 'grip space', () => {

		it( 'applies the grip pose with linear and angular velocity copies', () => {

			const controller = new WebXRController();
			const grip = controller.getGripSpace();
			const gripSpace = { name: 'grip-space' };

			const pose = createPose( {
				position: [ - 1, 0.5, 2 ],
				linearVelocity: [ 2, - 1, 0 ],
				angularVelocity: [ 0, 0.25, 0 ]
			} );

			const frame = createFrame( { poses: new Map( [ [ gripSpace, pose ] ] ) } );

			controller.update( { handedness: 'left', gripSpace }, frame, referenceSpace );

			expect( frame.getPose ).toHaveBeenCalledTimes( 1 );
			expect( frame.getPose ).toHaveBeenCalledWith( gripSpace, referenceSpace );

			expect( grip.matrix.toArray() ).toEqual( pose.transform.matrix );
			expect( grip.matrixWorldNeedsUpdate ).toBe( true );
			expect( grip.position.toArray() ).toEqual( [ - 1, 0.5, 2 ] );
			expect( grip.visible ).toBe( true );

			expect( grip.hasLinearVelocity ).toBe( true );
			expect( grip.linearVelocity.toArray() ).toEqual( [ 2, - 1, 0 ] );
			expect( grip.linearVelocity ).not.toBe( pose.linearVelocity );

			expect( grip.hasAngularVelocity ).toBe( true );
			expect( grip.angularVelocity.toArray() ).toEqual( [ 0, 0.25, 0 ] );
			expect( grip.angularVelocity ).not.toBe( pose.angularVelocity );

		} );

		it( 'keeps the grip invisible when the grip pose is missing', () => {

			const controller = new WebXRController();
			const grip = controller.getGripSpace();
			const gripSpace = { name: 'grip-space' };

			grip.visible = true;
			const updates = [];
			grip.addEventListener( 'gripUpdated', ( event ) => updates.push( event ) );
			grip.eventsEnabled = true;

			controller.update( { handedness: 'left', gripSpace }, createFrame(), referenceSpace );

			expect( grip.visible ).toBe( false );
			expect( grip.matrixWorldNeedsUpdate ).toBe( false );
			expect( updates ).toHaveLength( 0 );

		} );

		it( 'reports missing velocities as flags being false', () => {

			const controller = new WebXRController();
			const grip = controller.getGripSpace();
			const gripSpace = { name: 'grip-space' };

			grip.hasLinearVelocity = true;
			grip.hasAngularVelocity = true;

			const frame = createFrame( { poses: new Map( [ [ gripSpace, createPose( { position: [ 0, 1, 0 ] } ) ] ] ) } );

			controller.update( { handedness: 'left', gripSpace }, frame, referenceSpace );

			expect( grip.visible ).toBe( true );
			expect( grip.hasLinearVelocity ).toBe( false );
			expect( grip.hasAngularVelocity ).toBe( false );

		} );

		it( 'dispatches gripUpdated only when events are enabled', () => {

			const controller = new WebXRController();
			const grip = controller.getGripSpace();
			const gripSpace = { name: 'grip-space' };
			const inputSource = { handedness: 'right', gripSpace };

			const frame = createFrame( { poses: new Map( [ [ gripSpace, createPose( { position: [ 0, 0, 1 ] } ) ] ] ) } );

			const updates = [];
			grip.addEventListener( 'gripUpdated', ( event ) => updates.push( event ) );

			controller.update( inputSource, frame, referenceSpace );
			expect( updates ).toHaveLength( 0 );

			grip.eventsEnabled = true;
			controller.update( inputSource, frame, referenceSpace );

			expect( updates ).toHaveLength( 1 );
			expect( updates[ 0 ].type ).toBe( 'gripUpdated' );
			expect( updates[ 0 ].data ).toBe( inputSource );
			expect( updates[ 0 ].target ).toBe( controller );

		} );

		it( 'falls back to the grip pose for the target ray (ray space equals grip space)', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const grip = controller.getGripSpace();
			const targetRaySpace = { name: 'target-ray-space' };
			const gripSpace = { name: 'grip-space' };

			const gripPose = createPose( {
				position: [ 0.25, 0.5, 0.75 ],
				linearVelocity: [ 1, 2, 3 ],
				angularVelocity: [ 4, 5, 6 ]
			} );

			const frame = createFrame( { poses: new Map( [ [ gripSpace, gripPose ] ] ) } );
			const moves = [];
			targetRay.addEventListener( 'move', () => moves.push( 1 ) );

			controller.update( { handedness: 'right', targetRaySpace, gripSpace }, frame, referenceSpace );

			expect( frame.getPose ).toHaveBeenCalledTimes( 2 );
			expect( frame.getPose ).toHaveBeenNthCalledWith( 1, gripSpace, referenceSpace );
			expect( frame.getPose ).toHaveBeenNthCalledWith( 2, targetRaySpace, referenceSpace );

			expect( targetRay.matrix.toArray() ).toEqual( gripPose.transform.matrix );
			expect( targetRay.position.toArray() ).toEqual( [ 0.25, 0.5, 0.75 ] );
			expect( targetRay.hasLinearVelocity ).toBe( true );
			expect( targetRay.linearVelocity.toArray() ).toEqual( [ 1, 2, 3 ] );
			expect( targetRay.hasAngularVelocity ).toBe( true );
			expect( targetRay.angularVelocity.toArray() ).toEqual( [ 4, 5, 6 ] );
			expect( targetRay.visible ).toBe( true );
			expect( grip.visible ).toBe( true );
			expect( moves ).toHaveLength( 1 );

		} );

		it( 'does not fall back when no grip pose is available either', () => {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			controller.getGripSpace();

			const moves = [];
			targetRay.addEventListener( 'move', () => moves.push( 1 ) );

			controller.update(
				{ handedness: 'right', targetRaySpace: { name: 'target-ray-space' }, gripSpace: { name: 'grip-space' } },
				createFrame(),
				referenceSpace
			);

			expect( targetRay.visible ).toBe( false );
			expect( moves ).toHaveLength( 0 );

		} );

		it( 'ignores grip spaces that are not reported by the input source', () => {

			const controller = new WebXRController();
			const grip = controller.getGripSpace();
			const targetRay = controller.getTargetRaySpace();
			const targetRaySpace = { name: 'target-ray-space' };

			const frame = createFrame( { poses: new Map( [ [ targetRaySpace, createPose( { position: [ 1, 0, 0 ] } ) ] ] ) } );

			controller.update( { handedness: 'right', targetRaySpace }, frame, referenceSpace );

			expect( frame.getPose ).toHaveBeenCalledTimes( 1 );
			expect( frame.getPose ).toHaveBeenCalledWith( targetRaySpace, referenceSpace );
			expect( grip.visible ).toBe( false );
			expect( targetRay.visible ).toBe( true );

		} );

	} );

	describe( 'hand space', () => {

		const wrist = { jointName: 'wrist' };
		const indexTip = { jointName: 'index-finger-tip' };
		const thumbTip = { jointName: 'thumb-tip' };
		const targetRaySpace = { name: 'target-ray-space' };
		const gripSpace = { name: 'grip-space' };

		function createHandInputSource() {

			return {
				handedness: 'left',
				hand: new Map( [
					[ 'wrist', wrist ],
					[ 'index-finger-tip', indexTip ],
					[ 'thumb-tip', thumbTip ]
				] ),
				targetRaySpace,
				gripSpace
			};

		}

		function createHandController( { pinching = false } = {} ) {

			const controller = new WebXRController();
			const targetRay = controller.getTargetRaySpace();
			const grip = controller.getGripSpace();
			const hand = controller.getHandSpace();

			hand.inputState.pinching = pinching;

			const events = [];
			hand.addEventListener( 'pinchstart', ( event ) => events.push( event ) );
			hand.addEventListener( 'pinchend', ( event ) => events.push( event ) );

			return { controller, targetRay, grip, hand, events };

		}

		function jointFrame( { indexPosition, thumbPosition, missingWrist = false } ) {

			const jointPoses = new Map();

			if ( ! missingWrist ) jointPoses.set( wrist, createPose( { position: [ 0, 1, 0 ], radius: 0.02 } ) );

			jointPoses.set( indexTip, createPose( { position: indexPosition, radius: 0.008 } ) );
			jointPoses.set( thumbTip, createPose( { position: thumbPosition, radius: 0.009 } ) );

			return createFrame( {
				jointPoses,
				poses: new Map( [ [ targetRaySpace, createPose( { position: [ 0, 1.5, 0.2 ] } ) ] ] )
			} );

		}

		it( 'creates and updates joints from the joint poses', () => {

			const { controller, targetRay, grip, hand } = createHandController();

			const frame = jointFrame( { indexPosition: [ 0, 1, 0.1 ], thumbPosition: [ 0, 1, 0.12 ] } );

			controller.update( createHandInputSource(), frame, referenceSpace );

			expect( hand.visible ).toBe( true );

			const wristJoint = hand.joints.wrist;
			expect( wristJoint ).toBeDefined();
			expect( wristJoint.matrixAutoUpdate ).toBe( false );
			expect( wristJoint.visible ).toBe( true );
			expect( wristJoint.matrixWorldNeedsUpdate ).toBe( true );
			expect( wristJoint.jointRadius ).toBe( 0.02 );
			expect( wristJoint.position.toArray() ).toEqual( [ 0, 1, 0 ] );
			expect( hand.children ).toContain( wristJoint );

			expect( hand.joints[ 'index-finger-tip' ].jointRadius ).toBe( 0.008 );
			expect( hand.joints[ 'index-finger-tip' ].position.toArray() ).toEqual( [ 0, 1, 0.1 ] );
			expect( hand.joints[ 'thumb-tip' ].jointRadius ).toBe( 0.009 );

			expect( frame.getJointPose ).toHaveBeenCalledTimes( 3 );
			expect( frame.getJointPose ).toHaveBeenCalledWith( wrist, referenceSpace );
			expect( frame.getJointPose ).toHaveBeenCalledWith( indexTip, referenceSpace );

			// hand input sources take precedence over the grip space
			expect( grip.visible ).toBe( false );
			expect( frame.getPose ).not.toHaveBeenCalledWith( gripSpace, referenceSpace );
			expect( frame.getPose ).toHaveBeenCalledWith( targetRaySpace, referenceSpace );
			expect( targetRay.visible ).toBe( true );

		} );

		it( 'marks joints without a pose as invisible and reuses joint instances', () => {

			const { controller, hand } = createHandController();
			const inputSource = createHandInputSource();

			controller.update(
				inputSource,
				jointFrame( { indexPosition: [ 0, 1, 0.1 ], thumbPosition: [ 0, 1, 0.12 ] } ),
				referenceSpace
			);

			const wristJoint = hand.joints.wrist;
			expect( wristJoint.visible ).toBe( true );

			controller.update(
				inputSource,
				jointFrame( { indexPosition: [ 0, 2, 0.1 ], thumbPosition: [ 0, 2, 0.12 ], missingWrist: true } ),
				referenceSpace
			);

			expect( hand.joints.wrist ).toBe( wristJoint );
			expect( wristJoint.visible ).toBe( false );
			expect( wristJoint.jointRadius ).toBe( 0.02 );
			expect( hand.children.filter( ( child ) => child === wristJoint ) ).toHaveLength( 1 );
			expect( hand.joints[ 'index-finger-tip' ].position.toArray() ).toEqual( [ 0, 2, 0.1 ] );

		} );

		it( 'hides the hand space when the input source provides no hand', () => {

			const { controller, hand, grip } = createHandController();
			const frame = createFrame( {
				poses: new Map( [ [ gripSpace, createPose( { position: [ 0, 0, 1 ] } ) ] ] )
			} );

			controller.update( { handedness: 'left', targetRaySpace, gripSpace }, frame, referenceSpace );

			expect( hand.visible ).toBe( false );
			expect( grip.visible ).toBe( true );

		} );

		describe( 'pinch detection', () => {

			it( 'dispatches pinchstart once when the fingers come close together', () => {

				const { controller, hand, events } = createHandController();
				const inputSource = createHandInputSource();

				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.01, 0, 0 ] } ),
					referenceSpace
				);

				expect( hand.inputState.pinching ).toBe( true );
				expect( events ).toHaveLength( 1 );
				expect( events[ 0 ].type ).toBe( 'pinchstart' );
				expect( events[ 0 ].handedness ).toBe( 'left' );
				expect( events[ 0 ].target ).toBe( controller );

				// still pinching, no duplicate event
				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.01, 0, 0 ] } ),
					referenceSpace
				);

				expect( events ).toHaveLength( 1 );
				expect( hand.inputState.pinching ).toBe( true );

			} );

			it( 'dispatches pinchend once when the fingers separate again', () => {

				const { controller, hand, events } = createHandController( { pinching: true } );
				const inputSource = createHandInputSource();

				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.03, 0, 0 ] } ),
					referenceSpace
				);

				expect( hand.inputState.pinching ).toBe( false );
				expect( events ).toHaveLength( 1 );
				expect( events[ 0 ].type ).toBe( 'pinchend' );
				expect( events[ 0 ].handedness ).toBe( 'left' );
				expect( events[ 0 ].target ).toBe( controller );

				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.03, 0, 0 ] } ),
					referenceSpace
				);

				expect( events ).toHaveLength( 1 );

			} );

			it( 'stays in the hysteresis band without changing state', () => {

				const { controller, hand, events } = createHandController();
				const inputSource = createHandInputSource();

				// 0.016 is above the pinch start threshold but below the release threshold
				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.016, 0, 0 ] } ),
					referenceSpace
				);

				expect( hand.inputState.pinching ).toBe( false );
				expect( events ).toHaveLength( 0 );

				// 0.0249 is below the release threshold, so the pinch is kept alive
				hand.inputState.pinching = true;

				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.0249, 0, 0 ] } ),
					referenceSpace
				);

				expect( hand.inputState.pinching ).toBe( true );
				expect( events ).toHaveLength( 0 );

			} );

			it( 'starts and ends pinches just outside the hysteresis band', () => {

				const { controller, hand, events } = createHandController();
				const inputSource = createHandInputSource();

				// 0.0149 is below the pinch start threshold
				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.0149, 0, 0 ] } ),
					referenceSpace
				);

				expect( hand.inputState.pinching ).toBe( true );
				expect( events.map( ( event ) => event.type ) ).toEqual( [ 'pinchstart' ] );

				// 0.0251 is above the pinch release threshold
				controller.update(
					inputSource,
					jointFrame( { indexPosition: [ 0, 0, 0 ], thumbPosition: [ 0.0251, 0, 0 ] } ),
					referenceSpace
				);

				expect( hand.inputState.pinching ).toBe( false );
				expect( events.map( ( event ) => event.type ) ).toEqual( [ 'pinchstart', 'pinchend' ] );

			} );

		} );

	} );

} );
